function persist(notify=true){if(!startup.playing)return false;if(sessionReloading||sessionLoadFailed)return false;if(coop.active||coopPending){if(notify)toast('Online expeditions save automatically on the server');return false;}if(labActive){if(notify)toast('Campaign saves are locked while the isolated lab is open');return false;}if(!ensureSessionRevision())return false;try{storeSession(localStorage,state,true,persistedSessionRevision);saveStatus='Saved '+new Date().toLocaleTimeString();if(notify)toast('World saved on this device');return true;}catch(error){const checkpointBlocked=error instanceof Error&&error.name==='RollbackCheckpointError';saveStatus=checkpointBlocked?'Save paused · invalid rollback checkpoint':'Save failed';toast(checkpointBlocked?'A rollback checkpoint is invalid. Your stored world is unchanged. Export current progress and the last stored checkpoint from Settings before reloading.':'Storage unavailable. Export your save from Settings.');return false;}}
