function renderRestartPanel(kind:'restart'|'recover'){
 if(!ensureSessionRevision())return;
 const identity={generation:state.generation,seed:state.seed,...(state.regional?{regional:state.regional}:{})},epoch=zoneEpoch,recover=kind==='recover';
 const valid=()=>!sessionReloading&&!sessionLoadFailed&&!labActive&&!coop.active&&!coopPending&&coop.status!=='connecting'&&!transitioning&&physicsReady&&!panel.hidden&&panel.dataset.type===kind&&sameWorld(state,identity)&&zoneEpoch===epoch;
 let operation:ReturnType<typeof createSessionResetOperation>,historySaves:ReturnType<typeof sessionRecoverySaves>,original:string|null,selectedKey:string|undefined;
 try{historySaves=sessionRecoverySaves(localStorage,state);original=preResetSave(localStorage,state);selectedKey=historySaves.find(row=>row.raw===original)?.key??historySaves[0]?.key;operation=createSessionResetOperation(localStorage,state,recover?'restore':'restart',recover?selectedKey:undefined);}catch{toast('No valid recovery is available, or storage has changed. Your current world is unchanged.');openPanel('settings');return;}
 panel.innerHTML=`<button class="close" aria-label="Cancel and close">×</button><span class="eyebrow">Personal solo save · seed ${state.seed}</span><h2>${recover?'Recover earlier progress?':'Restart this world?'}</h2><p class="restart-warning">${recover?'The selected recovery becomes this world’s active progress. Your current run is kept as another protected entry in recovery history.':'This starts the same seed and world type from the beginning. Inventory, projects, enemies, gathered resources and your position all start fresh.'}</p><p>${state.regional?'10 km² frontier':state.generation===1?'Original valley':'Connected valley'} · generation ${state.generation} · seed ${state.seed}</p>${recover?'<label for="reset-checkpoint">Choose retained progress</label><select id="reset-checkpoint"></select><p id="reset-preview"></p><button id="reset-export">Export selected recovery</button>':''}<p>${recover?'All existing protected copies are retained.':original?'Your original protected recovery copy is kept unchanged. This run is also kept in recovery history, so you can recover either later.':'Your current progress is kept as a protected recovery copy, separate from rolling autosaves.'} Other seeds, valley/frontier saves, settings and shared online rooms are unchanged.</p><p>The full game reloads after confirmation. To explore another seed, cancel and choose a frontier instead.</p><div class="row"><button id="reset-cancel">Cancel · keep playing</button><button id="reset-confirm" class="danger-confirm">${recover?'Recover & reload':'Restart & reload'}</button></div><p id="reset-error" role="status"></p>`;
 panel.querySelector<HTMLButtonElement>('.close')!.onclick=closePanel;$('reset-cancel').onclick=closePanel;
 const button=$('reset-confirm') as HTMLButtonElement;button.disabled=!valid()||recover&&!selectedKey;
 if(recover){const select=$('reset-checkpoint') as HTMLSelectElement;for(const row of historySaves){const option=document.createElement('option');option.value=row.key;option.textContent=`Before ${row.kind==='restart'?'restart':'recovery'} #${row.epoch}${row.raw===original?' · original protected run':''}`;select.append(option);}select.value=selectedKey??'';
  const preview=()=>{const row=historySaves.find(item=>item.key===select.value),saved=row?parseSave(row.raw):null;$('reset-preview').textContent=saved?`${saved.zone==='valley'?'Surface':saved.zone==='cave'?'River cave':'Echo Vault'} · ${saved.collected.length} collected caches · ${saved.inventory.scrap} scrap · ${saved.inventory.core} cores · ${saved.jobs.renown} renown · ${Math.round(saved.player.hp)}% suit`:'Recovery unavailable';};preview();
  select.onchange=()=>{if(!valid())return;try{selectedKey=select.value;operation=createSessionResetOperation(localStorage,state,'restore',selectedKey);button.disabled=false;$('reset-error').textContent='';preview();}catch{button.disabled=true;$('reset-error').textContent='That recovery changed or is unavailable. Cancel and reopen recovery.';}};
  $('reset-export').onclick=()=>{const row=historySaves.find(item=>item.key===select.value);if(row)downloadSaveText(row.raw,`axiom-before-${row.kind}-${row.epoch}.json`);};
 }
 button.onclick=()=>{if(!ensureSessionRevision()||!valid()||button.disabled)return;button.disabled=true;let committed=false;try{committed=operation.commit().committed;}catch{$('reset-error').textContent='Could not commit the change. Your current world and protected recovery are unchanged. Export your save or free device storage, then reopen this confirmation.';return;}if(committed)reloadCommittedSession();};
 ($('reset-cancel') as HTMLButtonElement).focus({preventScroll:true});
}

